    #region LineImage
    public static void ClearLineImage()
    {
        solidLineImage = null;
        dottedLineImage = null;
        dashedLineImage = null;
        longDashedLineImage = null;
        dashSingleDottedLineImage = null;
        dashDoubleDottedLineImage = null;
    }
    private static DrawingImage MakeLineImage(string path)
    {
        Geometry checkmarkGeometry = Geometry.Parse(path);
        var brush = Brushes.White;
        var geometryDrawing = new GeometryDrawing
        {
            Geometry = checkmarkGeometry,
            Pen = new Pen(brush, 1),
            Brush = Brushes.Transparent,
        };
        var drawingImage = new DrawingImage(geometryDrawing);
        drawingImage.Freeze();

        return drawingImage;
    }

    #endregion

    #region MakeImage()
    private static PathGeometry MakePathGeometry(string source) => PathGeometry.CreateFromGeometry(PathGeometry.Parse(source));
    private static ImageSource MakeImage(List<(string path, string color)> pathList)
    {
        DrawingGroup drawingGroup = new();
        foreach (var (path, color) in pathList)
        {
            Geometry geometry = Geometry.Parse(path);
            Brush brush = new SolidColorBrush((Color)ColorConverter.ConvertFromString(color));
            var drawing = new GeometryDrawing
            {
                Geometry = geometry,
                Brush = brush,
            };
            drawingGroup.Children.Add(drawing);
        }

        DrawingImage drawingImage = new()
        {
            Drawing = drawingGroup
        };
        drawingImage.Freeze();
        return drawingImage;
    }

    private static ImageSource MakeImage(string source, bool isFlip = false, double imageWidth = 42, double borderWidth = 48)
    {
        source = SvgResizeAndCenter(source, imageWidth, borderWidth);
        Geometry geometry = Geometry.Parse(source);
        //상하반전
        if (isFlip)
        {
            var transform = new ScaleTransform(1, -1, borderWidth / 2, borderWidth / 2);
            if (geometry.IsFrozen)
                geometry = geometry.Clone();

            geometry.Transform = transform;
        }

        var drawing = new GeometryDrawing
        {
            Geometry = geometry,
            Brush = Brushes.DimGray,
        };

        var drawingGroup = new DrawingGroup();
        drawingGroup.Children.Add(drawing);

        var image = new DrawingImage(drawingGroup);
        image.Freeze();
        return image;
    }

    private static string SvgResizeAndCenter(string d, double imageWidth, double borderWidth)
    {
        // 1. Geometry 파싱
        var geometry = PathGeometry.CreateFromGeometry(Geometry.Parse(d));

        // 2. 실제 도형 bounds만 추출 (MoveTo만 있는 segment는 제외)
        var outlined = geometry.GetOutlinedPathGeometry();
        var bounds = outlined.Bounds;

        // 3. 스케일 및 오프셋 계산 (여백 제외, 도형 크기 38, 48x48 중앙)
        double scale = imageWidth / Math.Max(bounds.Width, bounds.Height);
        double newWidth = bounds.Width * scale;
        double newHeight = bounds.Height * scale;
        double offsetX = (borderWidth - newWidth) / 2.0 - bounds.X * scale;
        double offsetY = (borderWidth - newHeight) / 2.0 - bounds.Y * scale;

        var transform = new MatrixTransform(scale, 0, 0, scale, offsetX, offsetY);
        var transformedGeometry = outlined.Clone();
        transformedGeometry.Transform = transform;
        transformedGeometry = transformedGeometry.GetOutlinedPathGeometry();

        // 4. d 속성 문자열로 변환 (소수점 2자리)
        string dOut = Regex.Replace(
            transformedGeometry.ToString(CultureInfo.InvariantCulture),
            @"-?\d+(\.\d+)?",
            m =>
            {
                if (double.TryParse(m.Value, NumberStyles.Float, CultureInfo.InvariantCulture, out double v))
                    return v.ToString("0.##", CultureInfo.InvariantCulture);
                return m.Value;
            });

        // 5. 앞에 M48 48z M0 0z 추가
        return "M48 48z M0 0z " + dOut;
    }
    #endregion
